<script setup>
import { ref, computed } from 'vue'
const menus=[['總覽','◫'],['會員管理','♧'],['加入管理','↗'],['分類管理','▦'],['操作紀錄','◷']]
const page=ref('總覽'),memberName=ref(''),accountQuery=ref(''),emailQuery=ref(''),roleQuery=ref('全部角色'),status=ref('全部狀態'),selected=ref(null),dialog=ref(null),toast=ref(''),tab=ref('記帳'),mode=ref('邀請制'),mobile=ref(false),logDetail=ref(null)
const members=ref(['陳維克','林小雨','王家明','陳安安','陳莉莉','黃凱文','林美慧','蔡立歐'].map((name,i)=>({id:i,name,account:['victor','lin_yu','james.w','chen.ann','lily_chen','huang.k','may.lin','leo.tsai'][i],active:![4,7].includes(i),role:i===0?'管理員':'一般會員',date:`2026/10/${String(i*2+1).padStart(2,'0')}`})))
const logs=ref([{at:'2026/10/20 10:42',action:'停用會員',target:'蔡立歐',detail:'啟用 → 停用；示意撤銷所有登入。'},{at:'2026/10/19 16:25',action:'新增分類',target:'瑜珈',detail:'建立共用運動分類。'},{at:'2026/10/18 09:10',action:'編輯分類',target:'日常飲食',detail:'餐飲 → 日常飲食。'},{at:'2026/10/17 14:30',action:'停用會員',target:'陳莉莉',detail:'啟用 → 停用；示意撤銷所有登入。'}])
const categories=ref([{id:1,type:'記帳',name:'日常飲食',group:'支出',items:'早餐、午餐、晚餐、飲料',active:true},{id:2,type:'記帳',name:'交通出行',group:'支出',items:'捷運、油資、停車',active:true},{id:3,type:'記帳',name:'居家生活',group:'支出',items:'生活用品、水電、房租',active:true},{id:4,type:'記帳',name:'薪資收入',group:'收入',items:'薪資、獎金',active:true},{id:5,type:'記帳',name:'其他支出',group:'支出',items:'其他',active:false},{id:6,type:'運動',name:'跑步',group:'有氧運動',items:'戶外跑步、跑步機',active:true},{id:7,type:'運動',name:'重量訓練',group:'肌力訓練',items:'上肢、下肢、核心',active:true},{id:8,type:'運動',name:'瑜珈',group:'伸展運動',items:'瑜珈、伸展',active:true}])
const editor=ref(null),logQuery=ref(''),current=ref(1),invite=ref(false),inviteReady=ref(false)
const appliedFilters=ref({name:'',account:'',email:'',role:'全部角色',status:'全部狀態'})
const matches=(value,query)=>value.toLowerCase().includes(query.trim().toLowerCase())
const filtered=computed(()=>members.value.filter(m=>
  matches(m.name,appliedFilters.value.name)&&
  matches(m.account,appliedFilters.value.account)&&
  matches(`${m.account}@example.com`,appliedFilters.value.email)&&
  (appliedFilters.value.role==='全部角色'||m.role===appliedFilters.value.role)&&
  (appliedFilters.value.status==='全部狀態'||m.active===(appliedFilters.value.status==='啟用中'))
))
const count=computed(()=>members.value.filter(m=>m.active).length)
const totalPages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/5)))
const visible=computed(()=>filtered.value.slice((current.value-1)*5,current.value*5))
const filteredLogs=computed(()=>logs.value.filter(l=>(l.action+l.target+'陳維克').includes(logQuery.value)))
const subtitles={'總覽':'掌握這個小圈子的近況。','會員管理':'照顧每一位成員，讓相聚更簡單。','加入管理':'一起確認最適合親友的加入方式。','分類管理':'讓每筆日常，都有合適的位置。','操作紀錄':'每一次調整，都有跡可循。'}
let timer
function note(s){toast.value=s;clearTimeout(timer);timer=setTimeout(()=>toast.value='',3500)}
function go(p){page.value=p;mobile.value=false}
function record(action,target,detail){logs.value.unshift({at:new Intl.DateTimeFormat('sv-SE',{dateStyle:'short',timeStyle:'short',timeZone:'Asia/Taipei'}).format(new Date()),action,target,detail})}
function resetMemberFilters(){memberName.value='';accountQuery.value='';emailQuery.value='';roleQuery.value='全部角色';status.value='全部狀態'}
function searchMembers(){appliedFilters.value={name:memberName.value,account:accountQuery.value,email:emailQuery.value,role:roleQuery.value,status:status.value};current.value=1}
function browse(s='全部狀態'){resetMemberFilters();status.value=s;searchMembers();go('會員管理')}
function ask(item,kind){dialog.value={item,kind,title:kind==='session'?'撤銷所有登入？':`${item.active?'停用':'啟用'}${kind==='member'?'會員':'分類'}？`}}
function accept(){const {item,kind}=dialog.value;if(kind==='session')record('撤銷登入',item.name,'模擬撤銷此會員所有裝置的登入。');else{item.active=!item.active;record(`${item.active?'啟用':'停用'}${kind==='member'?'會員':'分類'}`,item.name,kind==='member'?'示意調整帳號狀態；停用時一併模擬撤銷所有登入。':'既有紀錄保留分類資訊。')}dialog.value=null;note('示意操作已完成，重新整理即可還原。')}
function edit(c){editor.value=c?{...c}:{id:null,type:tab.value,name:'',group:tab.value==='記帳'?'支出':'有氧運動',items:'',active:true}}
function save(){const e=editor.value;if(!e.name.trim())return;const old=categories.value.find(c=>c.id===e.id);if(old)Object.assign(old,{...e,name:e.name.trim()});else categories.value.push({...e,id:Date.now(),name:e.name.trim()});record(old?'編輯分類':'新增分類',e.name,`${e.type} / ${e.group} / ${e.items||'無細項'}`);editor.value=null;note('已儲存示意分類。')}
</script>

<template>
<div class="app">
<button v-if="mobile" class="shade" aria-label="關閉選單" @click="mobile=false"></button>
<aside :class="{open:mobile}"><a href="#" class="brand" @click.prevent="go('總覽')"><span class="logo">日</span><span>日常 <b>Daily</b><small>ADMIN WORKSPACE</small></span></a><div class="workspace"><span>⌂</span><div>親友的日常<small>一起，把生活整理好</small></div><i></i></div><p class="nav-caption">管理空間</p><nav><button v-for="[name,icon] in menus" :key="name" :class="{active:page===name}" @click="go(name)"><span>{{icon}}</span>{{name==='總覽'?'管理總覽':name}}<small v-if="name==='加入管理'">規劃</small></button></nav><div class="aside-bottom"><div class="tip"><span>✧</span><strong>先試試，再一起決定</strong><p>這裡是互動 Demo，所有資料與操作都是示意。</p></div><div class="profile"><span class="avatar">維</span><div>陳維克<small>管理員 · Demo 身分</small></div></div></div></aside>
<div class="content"><header><div><button class="menu" aria-label="開啟選單" @click="mobile=true">☰</button><span>管理空間</span><i>/</i><strong>{{page==='總覽'?'管理總覽':page}}</strong></div><div><span class="demo-pill">● DEMO 預覽</span><span class="date">2026 年 10 月 20 日</span></div></header><main><div class="page-heading"><div><p class="eyebrow">DAILY / ADMIN</p><h1>{{page==='總覽'?'管理總覽':page}}<em v-if="page==='總覽'">.</em></h1><p>{{subtitles[page]}}</p></div><button v-if="page==='總覽'" class="primary" @click="browse()">管理會員 ↗</button><button v-if="page==='分類管理'" class="primary" @click="edit(null)">＋ 新增分類</button></div><div class="banner">ⓘ <span>目前為畫面與流程預覽，未連接正式資料。操作僅在本次頁面生效，重新整理即可還原。</span></div>
<template v-if="page==='總覽'"><section class="welcome"><div><p class="eyebrow">A LITTLE SPACE, FOR EVERYONE</p><h2>每個人的日常，都照顧到了。</h2><p>從成員到分類，讓這個小圈子維持剛剛好的秩序。</p><button class="link" @click="go('操作紀錄')">看看最近的異動 →</button></div><div class="art" aria-hidden="true"><div class="circle"></div><div class="back">✦</div><div class="paper"><strong>日常清單</strong><p>✓ &nbsp;好好生活</p><p>✓ &nbsp;彼此照顧</p><p>✓ &nbsp;一起記錄</p></div><span>✳</span></div></section><div class="stats"><button v-for="(s,i) in [['會員總數',members.length,'這個小圈子的所有成員'],['啟用中的會員',count,'帳號目前可以正常使用'],['已停用的會員',members.length-count,'可隨時查看與重新啟用']]" :key="s[0]" @click="browse(['全部狀態','啟用中','已停用'][i])"><span>{{s[0]}}<i>{{['♧','●','◌'][i]}}</i></span><strong>{{s[1]}}<small>位</small></strong><p>{{s[2]}} <b>↗</b></p></button></div><div class="overview-grid"><section class="panel"><div class="panel-heading"><div><h2>最近管理操作</h2><p>小小的調整，都記在這裡。</p></div><button class="link" @click="go('操作紀錄')">查看全部 →</button></div><div class="timeline"><button v-for="(l,i) in logs.slice(0,4)" :key="i" @click="logDetail=l"><span class="event-icon">{{l.action.includes('分類')?'▦':'♧'}}</span><div><strong>{{l.action}} <span>· {{l.target}}</span></strong><small>陳維克 · {{l.at}}</small></div><span class="arrow">›</span></button></div></section><section class="panel quick"><div class="panel-heading"><div><h2>常用入口</h2><p>讓管理，少幾個步驟。</p></div></div><button @click="browse()"><span class="quick-icon">♧</span><div><strong>查看會員</strong><small>帳號狀態與基本資料</small></div><span>↗</span></button><button @click="go('分類管理')"><span class="quick-icon peach">▦</span><div><strong>整理共用分類</strong><small>記帳與運動的分類設定</small></div><span>↗</span></button><p class="quiet">✧ &nbsp;管理空間，只保留需要的資訊。</p></section></div></template>
<template v-if="page==='會員管理'"><section class="panel"><div class="panel-heading"><div><h2>所有會員 <span class="count">{{members.length}}</span></h2><p>查找成員並管理帳號使用狀態。</p></div><span class="muted">示意資料</span></div><form class="filters member-filters" @submit.prevent="searchMembers">
<label class="filter-field">會員名稱<input v-model="memberName" placeholder="輸入會員名稱"></label>
<label class="filter-field">帳號<input v-model="accountQuery" placeholder="輸入帳號"></label>
<label class="filter-field">信箱<input v-model="emailQuery" type="text" inputmode="email" placeholder="輸入完整或部分信箱"></label>
<label class="filter-field">角色<select v-model="roleQuery"><option>全部角色</option><option>管理員</option><option>一般會員</option></select></label>
<label class="filter-field">狀態<select v-model="status"><option>全部狀態</option><option>啟用中</option><option>已停用</option></select></label>
<button type="submit" class="primary">查詢</button>
<button type="button" class="subtle" @click="resetMemberFilters">重設</button>
<p class="filter-hint">會員名稱、帳號、信箱支援模糊比對，不分英文大小寫；按「查詢」或 Enter 後套用條件。重設只清空條件。</p>
</form><div class="table-wrap"><table><thead><tr><th>會員</th><th>帳號 / Email</th><th>角色</th><th>狀態</th><th>建立日期</th><th class="right">操作</th></tr></thead><tbody><tr v-for="m in visible" :key="m.id"><td><div class="person"><span class="avatar" :class="['','peach','blue','lavender'][m.id%4]">{{m.name[1]}}</span><strong>{{m.name}}</strong></div></td><td>{{m.account}}<small class="muted block">{{m.account}}@example.com</small></td><td><span :class="{'admin-role':m.id===0}">{{m.role}}</span></td><td><span class="status" :class="{off:!m.active}">● {{m.active?'啟用中':'已停用'}}</span></td><td class="muted">{{m.date}}</td><td class="right"><button class="link" @click="selected=m">查看 ›</button></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty">找不到符合條件的會員。</td></tr></tbody></table></div><div class="pagination"><span>共 {{filtered.length}} 位會員 · 第 {{current}} / {{totalPages}} 頁</span><div><button :disabled="current===1" @click="current--">← 上一頁</button><button :disabled="current>=totalPages" @click="current++">下一頁 →</button></div></div></section><p class="footnote">會員詳情只呈現帳號管理所需資料。</p></template>
<template v-if="page==='分類管理'"><div class="tabs"><button v-for="t in ['記帳','運動']" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}分類</button></div><section class="panel"><div class="panel-heading"><div><h2>{{tab}}分類</h2><p>共用分類供成員建立紀錄時選用。</p></div></div><div class="table-wrap"><table><thead><tr><th>分類名稱</th><th>類型</th><th>細項</th><th>狀態</th><th class="right">操作</th></tr></thead><tbody><tr v-for="c in categories.filter(c=>c.type===tab)" :key="c.id"><td><strong>{{c.name}}</strong></td><td>{{c.group}}</td><td class="muted">{{c.items||'—'}}</td><td><span class="status" :class="{off:!c.active}">● {{c.active?'啟用中':'已停用'}}</span></td><td class="right"><button class="link" @click="edit(c)">編輯</button><button class="link danger-text" @click="ask(c,'category')">{{c.active?'停用':'啟用'}}</button></td></tr></tbody></table></div></section><p class="footnote">ⓘ 已使用的分類以停用方式處理，保留歷史紀錄的完整性。</p></template>
<template v-if="page==='加入管理'"><div class="tabs"><button v-for="t in ['邀請制','註冊審核制']" :key="t" :class="{active:mode===t}" @click="mode=t">{{t}}預覽</button></div><section class="panel join"><span class="join-icon">{{mode==='邀請制'?'↗':'✓'}}</span><p class="eyebrow">流程提案 · 尚未定案</p><h2>{{mode==='邀請制'?'邀請熟悉的人，一起加入日常。':'先提出申請，再由管理員確認。'}}</h2><p>{{mode==='邀請制'?'建立邀請 → 分享給親友 → 親友完成註冊':'親友填寫申請 → 管理員審核 → 核准後開通帳號'}}</p><button v-if="mode==='邀請制'" class="primary" @click="invite=true;inviteReady=false">＋ 試試建立邀請</button><div v-else class="application"><span class="avatar peach">晴</span><div><strong>林小晴</strong><small>sunny.lin · 註冊申請示例</small></div><button @click="note('已模擬拒絕，未變更真實帳號。');record('拒絕申請','林小晴','加入流程示意。')">模擬拒絕</button><button class="primary" @click="note('已模擬核准，未建立真實帳號。');record('核准申請','林小晴','加入流程示意。')">模擬核准</button></div><div class="join-note">目前正式系統已支援自行註冊。此處僅比較未來加入方式，尚未變更現有規則。</div></section></template>
<template v-if="page==='操作紀錄'"><section class="panel"><div class="panel-heading"><div><h2>管理異動紀錄</h2><p>操作時間以臺灣時間顯示。點選詳情查看異動內容。</p></div></div><div class="filters"><label class="search">⌕ <input v-model="logQuery" aria-label="搜尋操作紀錄" placeholder="搜尋操作、對象或管理員"></label><button @click="logQuery=''">重設</button></div><div class="table-wrap"><table><thead><tr><th>操作時間</th><th>操作人</th><th>動作</th><th>對象</th><th>結果</th><th class="right">操作</th></tr></thead><tbody><tr v-for="(l,i) in filteredLogs" :key="i"><td class="muted">{{l.at}}</td><td>陳維克</td><td>{{l.action}}</td><td>{{l.target}}</td><td><span class="status">完成</span></td><td class="right"><button class="link" @click="logDetail=l">詳情 ›</button></td></tr><tr v-if="!filteredLogs.length"><td colspan="6" class="empty">沒有符合條件的紀錄。</td></tr></tbody></table></div><div class="pagination">共 {{filteredLogs.length}} 筆示意紀錄</div></section></template>
<footer>日常 Daily <span>讓生活，有條不紊。</span><small>管理後台 · 互動原型 v0.1</small></footer>
</main></div>
<div v-if="selected" class="overlay" @click.self="selected=null"><section class="drawer" role="dialog" aria-modal="true" aria-labelledby="member-title"><div class="dialog-heading"><div><p class="eyebrow">MEMBER PROFILE</p><h2 id="member-title">會員詳情</h2></div><button aria-label="關閉會員詳情" class="close" @click="selected=null">×</button></div><div class="member-hero"><span class="avatar big">{{selected.name[1]}}</span><h2>{{selected.name}}</h2><p>@{{selected.account}}</p><span class="status" :class="{off:!selected.active}">● {{selected.active?'啟用中':'已停用'}}</span></div><h3>基本資料</h3><dl><div><dt>帳號</dt><dd>{{selected.account}}</dd></div><div><dt>姓名</dt><dd>{{selected.name}}</dd></div><div><dt>Email</dt><dd>{{selected.account}}@example.com</dd></div><div><dt>建立日期</dt><dd>{{selected.date}}</dd></div><div><dt>角色</dt><dd>{{selected.role}}</dd></div></dl><h3>帳號管理</h3><p class="muted">角色變更規則待確認，先預覽帳號狀態管理。</p><div class="actions"><button @click="ask(selected,'session')">撤銷所有登入</button><button :disabled="selected.id===0" :class="selected.active?'danger':'primary'" @click="ask(selected,'member')">{{selected.active?'停用帳號':'重新啟用'}}</button></div><p v-if="selected.id===0" class="footnote">Demo 中保護目前管理員，避免停用自己的帳號。</p><h3>相關管理紀錄</h3><div v-for="(l,i) in logs.filter(l=>l.target===selected.name).slice(0,3)" :key="i" class="mini-log"><strong>{{l.action}}</strong><small>{{l.at}} · 陳維克</small></div><p v-if="!logs.some(l=>l.target===selected.name)" class="muted">尚無管理異動紀錄。</p><button class="drawer-close" @click="selected=null">關閉詳情</button></section></div>
<div v-if="dialog" class="overlay centered" @click.self="dialog=null"><section class="modal" role="alertdialog" aria-modal="true" aria-labelledby="confirm-title"><span class="warning">!</span><h2 id="confirm-title">{{dialog.title}}</h2><p>操作對象：{{dialog.item.name}}</p><p>{{dialog.kind==='category'?'分類停用後不再提供新紀錄選用，既有紀錄保持原樣。':dialog.kind==='session'?'將模擬登出此會員的所有裝置。':'停用後將無法使用系統，並模擬撤銷所有登入；重新啟用後即可再次登入。'}}</p><div class="join-note">這是 Demo 操作，不影響正式資料。</div><div class="modal-actions"><button @click="dialog=null">取消</button><button class="primary" @click="accept">確認操作</button></div></section></div>
<div v-if="editor" class="overlay centered" @click.self="editor=null"><form class="modal" role="dialog" aria-modal="true" aria-labelledby="edit-title" @submit.prevent="save"><div class="dialog-heading"><h2 id="edit-title">{{editor.id?'編輯':'新增'}}{{editor.type}}分類</h2><button type="button" class="close" aria-label="關閉分類表單" @click="editor=null">×</button></div><label class="field">分類名稱<input v-model="editor.name" required maxlength="30" placeholder="例如：休閒娛樂"></label><label class="field">類型<select v-model="editor.group"><option v-for="g in editor.type==='記帳'?['支出','收入']:['有氧運動','肌力訓練','伸展運動','其他']" :key="g">{{g}}</option></select></label><label class="field">細項<input v-model="editor.items" maxlength="150" placeholder="以頓號分隔，例如：電影、旅行"></label><div class="modal-actions"><button type="button" @click="editor=null">取消</button><button type="submit" class="primary">儲存示意分類</button></div></form></div>
<div v-if="logDetail" class="overlay centered" @click.self="logDetail=null"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="log-title"><div class="dialog-heading"><h2 id="log-title">操作詳情</h2><button class="close" aria-label="關閉操作詳情" @click="logDetail=null">×</button></div><dl><div><dt>操作人</dt><dd>陳維克</dd></div><div><dt>時間</dt><dd>{{logDetail.at}}</dd></div><div><dt>動作</dt><dd>{{logDetail.action}}</dd></div><div><dt>對象</dt><dd>{{logDetail.target}}</dd></div></dl><p class="detail-box">{{logDetail.detail}}</p><div class="modal-actions"><button class="primary" @click="logDetail=null">關閉</button></div></section></div>
<div v-if="invite" class="overlay centered" @click.self="invite=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="invite-title"><div class="dialog-heading"><h2 id="invite-title">建立邀請 · 流程預覽</h2><button class="close" aria-label="關閉邀請預覽" @click="invite=false">×</button></div><p>示意邀請可使用一次，有效期為建立後 7 天。</p><div v-if="inviteReady" class="detail-box"><strong>DEMO-DAILY-2026</strong><p>此代碼僅展示畫面，無法實際註冊。</p></div><div class="modal-actions"><button @click="invite=false">關閉</button><button v-if="!inviteReady" class="primary" @click="inviteReady=true;record('建立邀請','示意邀請','一次性邀請，有效期 7 天。')">產生示意邀請</button></div></section></div>
<div v-if="toast" class="toast" role="status">✓ {{toast}}<button aria-label="關閉提示" @click="toast=''">×</button></div>
</div>
</template>
